#!/usr/bin/env python3

import json
import sys
from pathlib import Path

import baserom as baserom_image

HEADER = (
    "/*\n"
    "PROGRESS_BAR_MONK_TONE.H\n"
    "do not edit this file; it is machine-generated.\n"
    "\n"
    "xbox adpcm, 22.05khz.\n"
    "*/\n"
    "\n"
    "byte compressed_monk_tone[]= {"
)

SYMBOL_NAME = "_compressed_monk_tone"
MONK_TONE_SIZE = 0x47DC

def main() -> None:
    if len(sys.argv) != 4:
        sys.exit(f"usage: {sys.argv[0]} <baserom> <symbols.json> <output>")
    baserom = Path(sys.argv[1])
    symbols_path = Path(sys.argv[2])
    output = Path(sys.argv[3])

    with open(symbols_path, "r", encoding="utf-8") as f:
        addresses = [s["address"] for s in json.load(f) if s["name"] == SYMBOL_NAME]
    if len(addresses) != 1:
        sys.exit(f"{symbols_path}: expected one {SYMBOL_NAME}, found {len(addresses)}")

    data = baserom_image.read(baserom, addresses[0], MONK_TONE_SIZE)
    if len(data) != MONK_TONE_SIZE:
        sys.exit(f"{baserom}: couldn't read the monk tone")

    text = HEADER
    for i, b in enumerate(data):
        if i % 12 == 0:
            text += "\n\t"
        text += f"0x{b:02x}, "
    text += "\n};\n"

    # Only rewrite when the contents change
    if output.is_file() and output.read_text(encoding="utf-8") == text:
        return
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(text, encoding="utf-8", newline="\n")

if __name__ == "__main__":
    main()
